// BALANCED GROUP FORMATION ALGORITHM
// Goal: Create diverse, balanced groups of 5-6 people

const rsvps = $('Get All RSVPs This Week').first().json.records || [];
const users = $('Get All Users').first().json.records || [];
const recentDinners = $('Get Recent Dinners (4 weeks)').first().json.records || [];

// Create user lookup map
const userMap = {};
users.forEach(user => {
  userMap[user.id] = user.fields;
});

// Track recent groupings to avoid repeats
const recentPairings = new Set();
recentDinners.forEach(dinner => {
  const attendees = dinner.fields['Attendees'] || [];
  for (let i = 0; i < attendees.length; i++) {
    for (let j = i + 1; j < attendees.length; j++) {
      const pair = [attendees[i], attendees[j]].sort().join('|');
      recentPairings.add(pair);
    }
  }
});

// Enrich RSVPs with user data
const enrichedRSVPs = rsvps.map(rsvp => {
  const userId = rsvp.fields['User'] ? rsvp.fields['User'][0] : null;
  const userData = userMap[userId] || {};

  return {
    rsvpId: rsvp.id,
    userId: userId,
    preferredDay: rsvp.fields['Preferred Day'] || 'Either',
    preferredAreas: rsvp.fields['Preferred Areas'] || [],
    dietaryRestrictions: rsvp.fields['Dietary Restrictions'] || [],
    topicsInterest: rsvp.fields['Topics of Interest'] || [],
    // User profile data
    name: userData['Full Name'] || 'Unknown',
    industry: userData['Industry'] || 'Other',
    jobTitle: userData['Job Title'] || '',
    company: userData['Company'] || '',
    experience: userData['Years Experience'] || 0,
    discordId: userData['Discord ID'] || '',
    location: userData['Location'] || ''
  };
}).filter(rsvp => rsvp.userId); // Remove any invalid RSVPs

if (enrichedRSVPs.length === 0) {
  return [{ json: { groups: [], message: 'No RSVPs to process' } }];
}

// Split by day preference
const wednesdayRSVPs = enrichedRSVPs.filter(r => r.preferredDay === 'Wednesday' || r.preferredDay === 'Either');
const thursdayRSVPs = enrichedRSVPs.filter(r => r.preferredDay === 'Thursday' || r.preferredDay === 'Either');

// Function to calculate diversity score between two people
function diversityScore(person1, person2) {
  let score = 0;

  // Different industries = higher diversity (20 points)
  if (person1.industry !== person2.industry) score += 20;

  // Different experience levels (15 points)
  const expDiff = Math.abs(person1.experience - person2.experience);
  if (expDiff >= 5) score += 15;
  else if (expDiff >= 2) score += 10;

  // Different companies (10 points)
  if (person1.company !== person2.company && person1.company && person2.company) score += 10;

  // Compatible dietary restrictions (20 points for compatibility)
  const diet1 = person1.dietaryRestrictions;
  const diet2 = person2.dietaryRestrictions;
  if (diet1.length === 0 && diet2.length === 0) score += 20; // No restrictions
  else {
    const hasCompatible = diet1.some(d => diet2.includes(d)) || diet1.length === 0 || diet2.length === 0;
    if (hasCompatible) score += 15;
  }

  // Shared topics of interest (10 points)
  const sharedTopics = person1.topicsInterest.filter(t => person2.topicsInterest.includes(t));
  if (sharedTopics.length > 0) score += 10;

  // Location overlap (10 points)
  const area1 = person1.preferredAreas;
  const area2 = person2.preferredAreas;
  const sharedAreas = area1.filter(a => area2.includes(a));
  if (sharedAreas.length > 0) score += 10;

  // Penalize recent pairings (-50 points)
  const pairKey = [person1.userId, person2.userId].sort().join('|');
  if (recentPairings.has(pairKey)) score -= 50;

  return score;
}

// Function to form balanced groups
function formGroups(people, targetSize = 6) {
  if (people.length === 0) return [];

  const groups = [];
  const assigned = new Set();

  // Shuffle for randomness
  const shuffled = [...people].sort(() => Math.random() - 0.5);

  while (shuffled.length - assigned.size >= targetSize) {
    const group = [];
    const available = shuffled.filter(p => !assigned.has(p.userId));

    if (available.length === 0) break;

    // Start with a random person
    const seed = available[Math.floor(Math.random() * available.length)];
    group.push(seed);
    assigned.add(seed.userId);

    // Add people to maximize diversity
    while (group.length < targetSize && available.filter(p => !assigned.has(p.userId)).length > 0) {
      const remaining = available.filter(p => !assigned.has(p.userId));

      // Calculate average diversity score with current group
      const scores = remaining.map(person => {
        const avgDiversity = group.reduce((sum, groupMember) => {
          return sum + diversityScore(person, groupMember);
        }, 0) / group.length;

        return { person, score: avgDiversity };
      });

      // Sort by diversity score (higher = more diverse)
      scores.sort((a, b) => b.score - a.score);

      // Pick from top 3 to add some randomness
      const topCandidates = scores.slice(0, Math.min(3, scores.length));
      const selected = topCandidates[Math.floor(Math.random() * topCandidates.length)].person;

      group.push(selected);
      assigned.add(selected.userId);
    }

    groups.push(group);
  }

  // Handle remaining people (less than targetSize)
  const unassigned = shuffled.filter(p => !assigned.has(p.userId));
  if (unassigned.length >= 3 && unassigned.length < targetSize) {
    // Create a smaller group if we have at least 3 people
    groups.push(unassigned);
  } else if (unassigned.length > 0 && groups.length > 0) {
    // Distribute to existing groups
    unassigned.forEach((person, idx) => {
      groups[idx % groups.length].push(person);
    });
  }

  return groups;
}

// Form groups for each day
const wednesdayGroups = formGroups(wednesdayRSVPs);
const thursdayGroups = formGroups(thursdayRSVPs);

// Calculate this week's dates
const now = new Date();
const monday = new Date(now);
monday.setDate(now.getDate() - now.getDay() + 1);
monday.setHours(0, 0, 0, 0);

const wednesday = new Date(monday);
wednesday.setDate(monday.getDate() + 2);

const thursday = new Date(monday);
thursday.setDate(monday.getDate() + 3);

// Format output
const allGroups = [
  ...wednesdayGroups.map((group, idx) => ({
    day: 'Wednesday',
    date: wednesday.toISOString().split('T')[0],
    groupNumber: idx + 1,
    people: group,
    size: group.length
  })),
  ...thursdayGroups.map((group, idx) => ({
    day: 'Thursday',
    date: thursday.toISOString().split('T')[0],
    groupNumber: idx + 1,
    people: group,
    size: group.length
  }))
];

return allGroups.map(group => ({ json: group }));

// Prepare notification data for each group member
const groupData = $('Balance Group Formation Algorithm').item.json;
const eventId = $('Create Dinner Event').item.json.id;

const notifications = groupData.people.map(person => ({
  json: {
    discordId: person.discordId,
    name: person.name.split(' ')[0],
    day: groupData.day,
    date: new Date(groupData.date).toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' }),
    groupSize: groupData.size,
    groupMembers: groupData.people.map(p => p.name).join(', '),
    eventId: eventId
  }
}));

return notifications;

